      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Neck pain history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Central/right paracervical ache described as tight muscles for about 6 weeks, with occasional brief sharp twinge on sudden turning. Worse with prolonged desk work, looking down at phone, and driving; better with heat, stretching, ibuprofen, and lying down. Sleep is somewhat disturbed by waking to change position. No arm pain, paraesthesia, weakness, clumsiness, gait change, bowel or bladder symptoms, or trauma."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Mood symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient describes being a bit cranky; denies low mood, anhedonia, and anxiety."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Neck inspection and palpation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Normal alignment, no deformity. Increased tone and tenderness to palpation of upper trapezius and paracervical muscles, right greater than left. No midline cervical spine tenderness."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Neck range of motion"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Rotation mildly reduced bilaterally with pain at end range; flexion and extension near full."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Upper limb neurological examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Power 5/5 in all myotomes; light-touch sensation intact; biceps, triceps, and brachioradialis reflexes 2+ and symmetrical. Spurling test negative; gait normal."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Left knee inspection and palpation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No obvious swelling, erythema, or deformity. Mild tenderness at the medial patellar margin and medial patellofemoral joint. No effusion."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Left knee range of motion"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Full range of motion with mild anterior pain on deep flexion."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Left knee stability and provocative tests"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "McMurray test negative; ligaments stable; stable to varus and valgus stress. Patellar grind reproduces symptoms."
      }
    },
