      "fullUrl": "https://example.org/fhir/Observation/observation-17",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-17",
        "status": "final",
        "code": {
          "text": "Gait and squat"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Gait normal; able to perform a partial squat with anterior knee pain."
      }
    },
