            "text": "200 mg as needed; patient reports taking 2–3 tablets per week for partial relief",
            "asNeededBoolean": true,
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 200,
                  "unit": "mg"
                }
              }
            ]
          }
        ]
