    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-2",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-2",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Ibuprofen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "400 mg orally three times daily as needed with food for up to 5–7 days during flares; avoid long-term continuous use; stop if indigestion or PR bleeding",
            "route": {
              "text": "oral"
            },
            "asNeededBoolean": true,
            "timing": {
